import { Component, HostListener, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';

@Component({
  selector: 'app-header',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './header.component.html',
  styleUrl: './header.component.scss',
})
export class HeaderComponent {
  isScrolled = signal(false);
  menuOpen = signal(false);
  isDarkTheme = signal(this.getTheme() === 'dark');

  navLinks = [
    { label: 'Biografia', href: '#biografia' },
    { label: 'Lezha', href: '#lezha' },
    { label: 'Galleria', href: '#galleria' },
    { label: 'Pubblicazioni', href: '#pubblicazioni' },
    { label: 'Video', href: '#video' },
    { label: 'Contatti', href: '#contatti' },
  ];

  @HostListener('window:scroll', [])
  onScroll() {
    this.isScrolled.set(window.scrollY > 50);
  }

  toggleTheme() {
    const newTheme = this.isDarkTheme() ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('theme', newTheme);
    this.isDarkTheme.set(newTheme === 'dark');
  }

  toggleMenu() {
    this.menuOpen.set(!this.menuOpen());
  }

  closeMenu() {
    this.menuOpen.set(false);
  }

  isAdmin(): boolean {
    return !!localStorage.getItem('auth_token');
  }

  private getTheme(): string {
    return localStorage.getItem('theme') || 'dark';
  }
}
<header class="header" [class.scrolled]="isScrolled()">
  <div class="header-container">
    <a href="#" class="logo">
      <span class="logo-circle">P·Z</span>
      <span class="logo-text">Pualin Zefi</span>
    </a>

    <nav class="nav-desktop">
      <a *ngFor="let link of navLinks" [href]="link.href" (click)="closeMenu()">
        {{ link.label }}
      </a>
      <a *ngIf="!isAdmin()" href="/login" class="login-link">
        <i class="fa-solid fa-sign-in-alt"></i> Accedi
      </a>
      <a *ngIf="isAdmin()" href="/admin" class="admin-link">
        <i class="fa-solid fa-cog"></i> Admin
      </a>
    </nav>

    <div class="header-actions">
      <button class="theme-toggle" (click)="toggleTheme()" [attr.aria-label]="isDarkTheme() ? 'Tema chiaro' : 'Tema scuro'">
        <i [ngClass]="isDarkTheme() ? 'fa-solid fa-sun' : 'fa-solid fa-moon'"></i>
      </button>

      <button class="menu-toggle" (click)="toggleMenu()" [class.active]="menuOpen()">
        <span></span>
        <span></span>
        <span></span>
      </button>
    </div>
  </div>

  <nav class="nav-mobile" [class.open]="menuOpen()">
    <a *ngFor="let link of navLinks" [href]="link.href" (click)="closeMenu()">
      {{ link.label }}
    </a>
    <a *ngIf="!isAdmin()" href="/login" (click)="closeMenu()">
      <i class="fa-solid fa-sign-in-alt"></i> Accedi
    </a>
    <a *ngIf="isAdmin()" href="/admin" (click)="closeMenu()">
      <i class="fa-solid fa-cog"></i> Admin
    </a>
  </nav>
</header>
